/* ----------------------------------------------------------- biomarkers */

export type Biomarker = {
  short: string;
  /** The expansion. Requirement: never ship a bare abbreviation. */
  full: Bi;
  unit: Bi;
  value: string;
  healthy: boolean;
  status: Bi;
  why: Bi;
  points: number[];
};

